// Geometry-only few-row falsifier. No positive-field values or PDE evaluation.
#define main transition_localization_reference_not_invoked
#include "diagnose_transition_jets.cpp"
#undef main
#include <sstream>
using W=std::array<Real,9>;
Real LocalScale(const Grid&g,size_t p){Real largest=0;for(int A=0;A<3;++A){Real s=0;for(int a=0;a<3;++a)s+=g.geometry[p].J[A][a]*g.geometry[p].J[A][a];largest=std::max(largest,std::sqrt(s));}return 1/(g.n*largest);}
std::array<Real,2> Norm(const std::map<int,W>&weights){W sums{};for(const auto&e:weights)for(int f=0;f<9;++f)sums[f]+=std::abs(e.second[f]);return {*std::max_element(sums.begin(),sums.begin()+3),*std::max_element(sums.begin()+3,sums.end())};}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{auto g=MakeGrid();const size_t block_size=size_t(g.padded)*g.padded*g.padded;std::vector<int>reverse(g.count,-1);for(size_t p=0;p<g.active.size();++p)reverse[g.active[p]]=p;std::map<int,const Grid::Row*>halos;for(const auto&r:g.halos)halos[r.target]=&r;const auto selected=h::PunctureLogValuePlans::SelectTargets(g,h::PuncturePosition{},.24);std::set<int>positive_targets(selected.begin(),selected.end());V impulse(g.count,0),constant(g.count,0),noise(g.count,0);for(size_t p=0;p<g.active.size();++p){constant[g.active[p]]=1;noise[g.active[p]]=1e-12*std::sin(1.7*(p+1));}g.Fill(constant,1);g.Fill(noise,1);std::cout<<std::setprecision(17);
 for(size_t p:{size_t(0),size_t(6),size_t(126),size_t(14657),size_t(17922)}){const Real h=LocalScale(g,p);std::map<int,W>raw,composed;std::map<std::string,std::map<int,W>>category_weights;size_t modified=0,ghosts=0;std::map<std::string,int>categories;std::vector<std::string>records;
  auto add=[&](const std::string&cat,int id,const W&w,Real factor){for(int f=0;f<9;++f){composed[id][f]+=factor*w[f];category_weights[cat][id][f]+=factor*w[f];}};
  for(int index:Stencil(g,p)){impulse[index]=1;Real d[3],dd[3][3];g.Derivatives(impulse,0,p,d,dd);impulse[index]=0;W w{};for(int a=0;a<3;++a)w[a]=h*d[a];int f=3;for(int a=0;a<3;++a)for(int b=a;b<3;++b)w[f++]=h*h*dd[a][b];raw[index]=w;if(reverse[index]>=0){add("active",reverse[index],w,1);continue;}++ghosts;modified+=positive_targets.count(index);const auto&r=*halos.at(index);if(r.boundary_weight)throw std::runtime_error("predeclared few-row set unexpectedly reaches scri; no boundary omission allowed");const auto&receiver=g.mesh.blocks[index/block_size];std::set<int>donor_faces;int minlevel=99,maxlevel=-1;Real minimum=1e9,maximum=0,sum=0,l1=0;std::string category;
   for(const auto&e:r.entries){if(reverse[e.point]<0)throw std::runtime_error("halo donor is not active");const auto&donor=g.mesh.blocks[e.point/block_size];donor_faces.insert(donor.face);minlevel=std::min(minlevel,donor.refinement);maxlevel=std::max(maxlevel,donor.refinement);const auto&x=g.geometry[reverse[e.point]].x;minimum=std::min(minimum,Radius(x));maximum=std::max(maximum,Radius(x));sum+=e.weight;l1+=std::abs(e.weight);}
   if(receiver.face<0&&*donor_faces.rbegin()>=0)category="Cartesian_receives_shell";else if(receiver.face>=0&&*donor_faces.begin()<0)category="shell_receives_Cartesian";else if(receiver.face<0&&(minlevel!=receiver.refinement||maxlevel!=receiver.refinement))category="Cartesian_coarse_fine";else if(receiver.face<0)category="Cartesian_same_level";else category="shell_to_shell";
   ++categories[category];for(const auto&e:r.entries)add(category,reverse[e.point],w,e.weight);add(category,reverse[r.entries[0].point],w,1-sum);l1+=std::abs(1-sum);const auto x=PaddedPoint(g,index);const int owner=g.mesh.Owner(x.data());Real q[3]{};if(owner>=0)g.mesh.Inverse(owner,x.data(),q);Real rawg=0,rawh=0;for(int a=0;a<3;++a)rawg=std::max(rawg,std::abs(w[a]));for(int a=3;a<9;++a)rawh=std::max(rawh,std::abs(w[a]));std::ostringstream line;line<<std::setprecision(17)<<"{\"phase\":\"halo_row\",\"query\":"<<p<<",\"target\":"<<index<<",\"category\":\""<<category<<"\",\"receiving_face\":"<<receiver.face<<",\"receiving_level\":"<<receiver.refinement<<",\"donor_level_min\":"<<minlevel<<",\"donor_level_max\":"<<maxlevel<<",\"donor_count\":"<<r.entries.size()<<",\"halo_L1\":"<<l1<<",\"halo_constant_sum\":"<<sum+1-sum<<",\"halo_radius\":"<<Radius(x.data())<<",\"donor_radius_min\":"<<minimum<<",\"donor_radius_max\":"<<maximum<<",\"owner\":"<<owner<<",\"owner_logical_radial\":"<<q[0]<<",\"raw_gradient_factor\":"<<rawg<<",\"raw_hessian_factor\":"<<rawh<<",\"positive_log_halo_override\":"<<(positive_targets.count(index)?"true":"false")<<"}";records.push_back(line.str());}
  const auto rn=Norm(raw),cn=Norm(composed);Real d[3],dd[3][3],constant_error=0;g.Derivatives(constant,0,p,d,dd);for(int a=0;a<3;++a){constant_error=std::max(constant_error,h*std::abs(d[a]));for(int b=0;b<3;++b)constant_error=std::max(constant_error,h*h*std::abs(dd[a][b]));}g.Derivatives(noise,0,p,d,dd);Real noise_change=0;for(int a=0;a<3;++a){noise_change=std::max(noise_change,h*std::abs(d[a]));for(int b=0;b<3;++b)noise_change=std::max(noise_change,h*h*std::abs(dd[a][b]));}if(noise_change>std::max(cn[0],cn[1])*1e-12+1e-20)throw std::runtime_error("ordinary halo impulse/noise mismatch");const auto&x=g.geometry[p].x;const auto&block=g.mesh.blocks[p/216];std::cout<<"{\"phase\":\"query\",\"point\":"<<p<<",\"xyz\":["<<x[0]<<','<<x[1]<<','<<x[2]<<"],\"face\":"<<block.face<<",\"level\":"<<block.refinement<<",\"h\":"<<h<<",\"raw_padded_gradient_L1\":"<<rn[0]<<",\"raw_padded_hessian_L1\":"<<rn[1]<<",\"ordinary_composed_gradient_L1\":"<<cn[0]<<",\"ordinary_composed_hessian_L1\":"<<cn[1]<<",\"positive_log_override_count\":"<<modified<<",\"ghost_points\":"<<ghosts<<",\"constant_scaled_jet_error\":"<<constant_error<<",\"noise_scaled_jet_change\":"<<noise_change<<",\"category_counts\":{";bool first=true;for(const auto&cat:categories){if(!first)std::cout<<',';first=false;std::cout<<'"'<<cat.first<<"\":"<<cat.second;}std::cout<<"},\"category_functional_norms\":{";first=true;for(const auto&cat:category_weights){if(!first)std::cout<<',';first=false;const auto norm=Norm(cat.second);std::cout<<'"'<<cat.first<<"\":["<<norm[0]<<','<<norm[1]<<']';}std::cout<<"}}\n";for(const auto&r:records)std::cout<<r<<'\n';}
 std::cout<<"{\"phase\":\"summary\",\"query_cells\":5,\"geometry_only\":true,\"no_positive_reconstruction_or_field_scaling_invoked\":true,\"no_PDE_or_evolution\":true,\"production_edited\":false}\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=1;}Kokkos::finalize();return code;}
